var data = [];

    var drivers = value.match(/<PhysicalDriveSmartStats[\s\S]*?<\/PhysicalDriveSmartStats>/g) || [];

    for (var i = 0; i < drivers.length; i++) {
        var e = drivers[i];

        var match = e.match(/id="(\d+)"/);

        if (match) {
            data.push({
                "{#DISKID}": match[1]
            });
        }
    }

    return JSON.stringify({ "data": data });

var volumes = [];
var currentVolume = null;
var currentDisk = null;
var mode = null;

var lines = value.split("\n");

for (var i = 0; i < lines.length; i++) {
    lines[i] = lines[i].trim();
    if (!lines[i]) continue;


    if (lines[i].indexOf("--VOLUME INFORMATION--") === 0) {
        if (currentVolume) volumes.push(currentVolume);
        currentVolume = { disks: [] };
        mode = "volume";
    }

    if (lines[i].indexOf("--DISKS IN VOLUME") === 0) {
        mode = "disks";
        currentDisk = null;
    }

    if (lines[i].indexOf("ID:") === 0) {
        if (mode === "disks") {
            currentDisk = {};
            currentVolume.disks.push(currentDisk);
            currentDisk.id = lines[i].split(":")[1].trim();
        }
    }

    if (mode === "volume" && lines[i].indexOf(":") !== -1 && lines[i].indexOf("--") !== 0) {
        var idx = lines[i].indexOf(":");
        var key = lines[i].substring(0, idx).trim().toLowerCase().replace(/\s+/g, "_");
        var val = lines[i].substring(idx + 1).trim();
         currentVolume[key] = val;
    }   
    if (mode === "disks" && currentDisk && lines[i].indexOf(":") !== -1 && lines[i].indexOf("--") !== 0)
    {
        var idx = lines[i].indexOf(":");
        var key = lines[i].substring(0, idx).trim().toLowerCase().replace(/\s+/g, "_");
        var val = lines[i].substring(idx + 1).trim();
        currentDisk[key] = val;
        currentDisk.volume = currentVolume.name; // ВАЖНО
    }
}
if (currentVolume)volumes.push(currentVolume);
return JSON.stringify({ volumes: volumes });
